{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "The Short-Circuit",
          "intent": "Establish Arthur's mundane life and the freak accident that triggers his transition.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Arthur's consciousness fades in the real world amidst electrical sparks."
        },
        {
          "section_id": 2,
          "title": "The Glitched Awakening",
          "intent": "Arthur wakes in the system and discovers his impossible 1 HP / 100% Crit Rate status.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Arthur confirms the 'Glass Cannon' status is not a temporary UI bug."
        },
        {
          "section_id": 3,
          "title": "Slumming It",
          "intent": "Arthur arrives at the Newbie Slums and realizes the immediate danger of his environment.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "Arthur stands at the entrance of the Newbie Slums with a glowing red warning over his head."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "The Zero-Tolerance Zone",
          "intent": "Arthur enters the tutorial and learns the movement mechanics required to avoid all damage.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Arthur reaches the first combat trial without losing his 1 HP."
        },
        {
          "section_id": 2,
          "title": "Precision Violence",
          "intent": "Arthur uses his 100% crit rate to one-shot tutorial mobs before they can react.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "The combat trial is cleared with a 'Flawless' rating."
        },
        {
          "section_id": 3,
          "title": "The Secret Shop",
          "intent": "Arthur finds a hidden vendor exploit before leaving the tutorial zone.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Arthur discovers a hidden vendor who sells items that shouldn't be available to level 1s."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "Turtle Hunting",
          "intent": "Arthur identifies high-level passive mobs that provide massive loot when overkilled.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Arthur locates the nesting grounds of the Crystal Tortoises."
        },
        {
          "section_id": 2,
          "title": "The Overkill Harvest",
          "intent": "Arthur systematically farms the tortoises, generating rare material drops.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Arthur secures his first 'overkill' drop from a Crystal Tortoise."
        },
        {
          "section_id": 3,
          "title": "Market Disruption",
          "intent": "Arthur attempts to sell his high-level loot, drawing unwanted attention from the merchant guild.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "A guild representative offers Arthur a 'deal' that smells like a trap."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "Shadow Boxing",
          "intent": "Arthur evades guild enforcers and flees into a restricted high-level dungeon.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Arthur enters the 'Shatter-Glass Crypt' to hide from guild enforcers."
        },
        {
          "section_id": 2,
          "title": "The Fragile Path",
          "intent": "Arthur navigates the crypt where the environment is as deadly as the monsters.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Arthur reaches the heart of the crypt without triggering a single trap."
        },
        {
          "section_id": 3,
          "title": "Accidental Aggro",
          "intent": "Arthur's attempt to hide leads him directly into a boss encounter meant for a full party.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Arthur accidentally triggers a party-requirement boss while solo."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "The Shield of Doom",
          "intent": "A 'heroic' Paladin intervenes, nearly killing Arthur with 'protection'.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The Paladin 'rescues' Arthur from a shadow, nearly crushing him with a heavy shield."
        },
        {
          "section_id": 2,
          "title": "Incompatible Tactics",
          "intent": "Arthur tries to use the Paladin as a distraction while maintaining his own stealth.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "The duo survives a series of encounters despite the Paladin's loud approach."
        },
        {
          "section_id": 3,
          "title": "The Thorns Threshold",
          "intent": "The party reaches the final boss, which possesses a lethal counter-mechanic.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The duo reaches the final chamber where a boss with an 'Aura of Thorns' resides."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "The Mirror Problem",
          "intent": "Arthur realizes he cannot hit the boss without killing himself via reflected damage.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The boss activates its Reflective Shell, halting Arthur's offense."
        },
        {
          "section_id": 2,
          "title": "Weaponized Math",
          "intent": "Arthur searches for a loophole in the damage calculation to bypass the reflection.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Arthur identifies a rounding error in the System's reflect logic."
        },
        {
          "section_id": 3,
          "title": "The Patch Trigger",
          "intent": "Arthur defeats the boss using the exploit, causing the System to flag him as a bug.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The boss falls to a mathematical technicality, but the System triggers a 'Balance Patch' alert."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "Digital Decay",
          "intent": "The world begins to break down as the System attempts to delete Arthur's character.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The world begins to pixelate as the 'Balance Patch' initiates."
        },
        {
          "section_id": 2,
          "title": "The Outrun",
          "intent": "Arthur races through the collapsing dungeon toward an unpatched legacy zone.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Arthur reaches the boundary of the Legacy Zone with the patch at his heels."
        },
        {
          "section_id": 3,
          "title": "Legacy Escape",
          "intent": "Arthur crosses into the safe zone, securing his existence and preparing for the next exploit.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Arthur escapes into a 'Legacy Zone' where the patch can't reach him, ready for the next exploit."
        }
      ]
    }
  ]
}

